/**
 * Sum Range
 * node starter/index.js
 */

const readline = require("node:readline");

function main() {
  const lines = [];
  const rl = readline.createInterface({ input: process.stdin });

  rl.on("line", (line) => {
    lines.push(line);
    if (lines.length < 2) return;

    // TODO: sum inclusive range with for loop

let start = Number(lines[0].trim());
let end = Number(lines[1].trim());
let sum = 0;

if (!Number.isInteger(start) || !Number.isInteger(end)){
console.log("ERROR: invalid range");
rl.close();
}

if (end < start) {
let bufferA = start;
let bufferB = end;
start = bufferB;
end =  bufferA;
}

for (let n = start; n <= end; n++){
    sum += n;
}
console.log("Sum: " + sum);
  });

}

main();

